import { create } from 'zustand';
import { persist } from 'zustand/middleware';

// Types
export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

export interface Session {
  id: string;
  title: string;
  messages: Message[];
  createdAt: number;
  updatedAt: number;
}

export interface Candidate {
  id: string;
  name: string;
  title: string;
  company: string;
  avatar?: string;
  matchScore: number;
  location?: string;
  experience?: string;
  exported?: boolean;
}

export interface ExportedFile {
  id: string;
  name: string;
  path: string;
  exportedAt: number;
  candidateId?: string;
}

export interface Settings {
  exportPath: string;
  theme: 'light' | 'dark';
}

export interface LoginState {
  isLoggedIn: boolean;
  phone?: string;
  cookies?: string;
}

interface AppState {
  // Data
  sessions: Session[];
  currentSessionId: string | null;
  messages: Message[];
  settings: Settings;
  exportedFiles: ExportedFile[];
  loginState: LoginState;
  candidates: Candidate[];

  // UI State
  leftSidebarOpen: boolean;
  rightSidebarOpen: boolean;
  showCandidates: boolean;
  showLoginModal: boolean;
  isLoading: boolean;

  // Current session getter
  getCurrentSession: () => Session | null;

  // Actions
  addSession: (session?: Partial<Session>) => string;
  updateSession: (id: string, updates: Partial<Session>) => void;
  setCurrentSession: (id: string | null) => void;
  deleteSession: (id: string) => void;

  addMessage: (message: Omit<Message, 'id' | 'timestamp'>) => void;
  clearMessages: () => void;

  updateSettings: (settings: Partial<Settings>) => void;

  addExportedFile: (file: Omit<ExportedFile, 'id' | 'exportedAt'>) => void;
  removeExportedFile: (id: string) => void;

  setLoginState: (state: Partial<LoginState>) => void;
  logout: () => void;

  setCandidates: (candidates: Candidate[]) => void;
  updateCandidate: (id: string, updates: Partial<Candidate>) => void;
  markCandidateExported: (id: string) => void;
  clearCandidates: () => void;

  toggleLeftSidebar: () => void;
  toggleRightSidebar: () => void;
  setShowCandidates: (show: boolean) => void;
  setShowLoginModal: (show: boolean) => void;
  setIsLoading: (loading: boolean) => void;
}

// Generate unique ID
const generateId = () => Math.random().toString(36).substring(2, 15);

export const useAppStore = create<AppState>()(
  persist(
    (set, get) => ({
      // Initial state
      sessions: [],
      currentSessionId: null,
      messages: [],
      settings: {
        exportPath: '',
        theme: 'dark',
      },
      exportedFiles: [],
      loginState: {
        isLoggedIn: false,
      },
      candidates: [],
      leftSidebarOpen: true,
      rightSidebarOpen: false,
      showCandidates: false,
      showLoginModal: false,
      isLoading: false,

      // Getters
      getCurrentSession: () => {
        const { sessions, currentSessionId } = get();
        return sessions.find((s) => s.id === currentSessionId) || null;
      },

      // Actions
      addSession: (sessionData) => {
        const id = generateId();
        const now = Date.now();
        const newSession: Session = {
          id,
          title: sessionData?.title || 'New Chat',
          messages: sessionData?.messages || [],
          createdAt: now,
          updatedAt: now,
        };
        set((state) => ({
          sessions: [newSession, ...state.sessions],
          currentSessionId: id,
          messages: newSession.messages,
        }));
        return id;
      },

      updateSession: (id, updates) => {
        set((state) => ({
          sessions: state.sessions.map((s) =>
            s.id === id ? { ...s, ...updates, updatedAt: Date.now() } : s
          ),
        }));
      },

      setCurrentSession: (id) => {
        const session = get().sessions.find((s) => s.id === id);
        set({
          currentSessionId: id,
          messages: session?.messages || [],
        });
      },

      deleteSession: (id) => {
        set((state) => {
          const newSessions = state.sessions.filter((s) => s.id !== id);
          let newCurrentId = state.currentSessionId;
          let newMessages: Message[] = [];

          if (state.currentSessionId === id) {
            newCurrentId = newSessions[0]?.id || null;
            newMessages = newSessions[0]?.messages || [];
          }

          return {
            sessions: newSessions,
            currentSessionId: newCurrentId,
            messages: newMessages,
          };
        });
      },

      addMessage: (message) => {
        const newMessage: Message = {
          ...message,
          id: generateId(),
          timestamp: Date.now(),
        };
        set((state) => {
          const messages = [...state.messages, newMessage];

          // Update session if exists
          if (state.currentSessionId) {
            const session = state.sessions.find((s) => s.id === state.currentSessionId);
            const title = session?.messages.length === 0 && message.role === 'user'
              ? message.content.slice(0, 50)
              : undefined;

            return {
              messages,
              sessions: state.sessions.map((s) =>
                s.id === state.currentSessionId
                  ? { ...s, messages, updatedAt: Date.now(), ...(title && { title }) }
                  : s
              ),
            };
          }

          return { messages };
        });
      },

      clearMessages: () => {
        set((state) => ({
          messages: [],
          sessions: state.sessions.map((s) =>
            s.id === state.currentSessionId ? { ...s, messages: [] } : s
          ),
        }));
      },

      updateSettings: (settings) => {
        set((state) => ({
          settings: { ...state.settings, ...settings },
        }));
      },

      addExportedFile: (file) => {
        const newFile: ExportedFile = {
          ...file,
          id: generateId(),
          exportedAt: Date.now(),
        };
        set((state) => ({
          exportedFiles: [newFile, ...state.exportedFiles],
        }));
      },

      removeExportedFile: (id) => {
        set((state) => ({
          exportedFiles: state.exportedFiles.filter((f) => f.id !== id),
        }));
      },

      setLoginState: (state) => {
        set((prev) => ({
          loginState: { ...prev.loginState, ...state },
        }));
      },

      logout: () => {
        set({
          loginState: { isLoggedIn: false },
          sessions: [],
          currentSessionId: null,
          messages: [],
          candidates: [],
        });
      },

      setCandidates: (candidates) => {
        set({ candidates });
      },

      updateCandidate: (id, updates) => {
        set((state) => ({
          candidates: state.candidates.map((c) =>
            c.id === id ? { ...c, ...updates } : c
          ),
        }));
      },

      markCandidateExported: (id) => {
        set((state) => ({
          candidates: state.candidates.map((c) =>
            c.id === id ? { ...c, exported: true } : c
          ),
        }));
      },

      clearCandidates: () => {
        set({ candidates: [], showCandidates: false });
      },

      toggleLeftSidebar: () => {
        set((state) => ({ leftSidebarOpen: !state.leftSidebarOpen }));
      },

      toggleRightSidebar: () => {
        set((state) => ({ rightSidebarOpen: !state.rightSidebarOpen }));
      },

      setShowCandidates: (show) => {
        set({ showCandidates: show });
      },

      setShowLoginModal: (show) => {
        set({ showLoginModal: show });
      },

      setIsLoading: (loading) => {
        set({ isLoading: loading });
      },
    }),
    {
      name: 'boss-recruiter-storage',
      partialize: (state) => ({
        sessions: state.sessions,
        currentSessionId: state.currentSessionId,
        settings: state.settings,
        exportedFiles: state.exportedFiles,
        loginState: state.loginState,
        leftSidebarOpen: state.leftSidebarOpen,
        rightSidebarOpen: state.rightSidebarOpen,
      }),
    }
  )
);

