import { useCallback } from 'react';
import { useAppStore, Candidate, Session } from '../stores/appStore';

const API_BASE_URL = 'http://localhost:3001';

interface ApiResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
}

interface LoginResponse {
  success: boolean;
  message: string;
  cookies?: string;
}

interface SendCodeResponse {
  success: boolean;
  message: string;
}

interface CandidatesResponse {
  candidates: Candidate[];
}

interface ExportResponse {
  success: boolean;
  filePath?: string;
  message: string;
}

interface SessionResponse {
  session: Session;
}

export function useApi() {
  const {
    addMessage,
    setCandidates,
    setIsLoading,
    addExportedFile,
    settings,
    loginState,
    markCandidateExported,
  } = useAppStore();

  // Login with phone
  const sendVerificationCode = useCallback(async (phone: string): Promise<SendCodeResponse> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/auth/send-code`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone }),
      });
      return await response.json();
    } catch (error) {
      return { success: false, message: 'Failed to send verification code' };
    }
  }, []);

  // Verify code and login
  const verifyCode = useCallback(async (phone: string, code: string): Promise<LoginResponse> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/auth/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone, code }),
      });
      const result = await response.json();
      if (result.success) {
        useAppStore.getState().setLoginState({
          isLoggedIn: true,
          phone,
          cookies: result.cookies,
        });
      }
      return result;
    } catch (error) {
      return { success: false, message: 'Failed to verify code' };
    }
  }, []);

  // Logout
  const logout = useCallback(async (): Promise<void> => {
    try {
      await fetch(`${API_BASE_URL}/api/auth/logout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });
    } catch (error) {
      console.error('Logout error:', error);
    }
    useAppStore.getState().logout();
  }, []);

  // Search candidates
  const searchCandidates = useCallback(async (query: string): Promise<void> => {
    setIsLoading(true);
    try {
      addMessage({ role: 'user', content: query });

      // Simulate API call - in real implementation this would call the backend
      // For now, we'll simulate a response
      const response = await fetch(`${API_BASE_URL}/api/candidates/search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(loginState.cookies && { 'Cookie': loginState.cookies }),
        },
        body: JSON.stringify({ query }),
      });

      if (response.ok) {
        const result: ApiResponse<CandidatesResponse> = await response.json();
        if (result.data?.candidates) {
          setCandidates(result.data.candidates);
          useAppStore.getState().setShowCandidates(true);
        }
      } else {
        addMessage({
          role: 'assistant',
          content: 'Failed to search candidates. Please try again.',
        });
      }
    } catch (error) {
      console.error('Search error:', error);
      addMessage({
        role: 'assistant',
        content: 'An error occurred while searching. Please check your connection.',
      });
    } finally {
      setIsLoading(false);
    }
  }, [addMessage, setCandidates, setIsLoading, loginState.cookies]);

  // Send chat message
  const sendMessage = useCallback(async (content: string): Promise<void> => {
    const { addSession, currentSessionId } = useAppStore.getState();

    // Create session if doesn't exist
    if (!currentSessionId) {
      addSession();
    }

    addMessage({ role: 'user', content });
    setIsLoading(true);

    try {
      // Simulate AI response - in real implementation this would call AI API
      // For now, we'll just echo back a response
      const response = await fetch(`${API_BASE_URL}/api/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(loginState.cookies && { 'Cookie': loginState.cookies }),
        },
        body: JSON.stringify({
          message: content,
          sessionId: currentSessionId,
        }),
      });

      if (response.ok) {
        const result = await response.json();
        if (result.response) {
          addMessage({ role: 'assistant', content: result.response });
        }
      } else {
        // Simulated response for demo
        setTimeout(() => {
          addMessage({
            role: 'assistant',
            content: `I received your message: "${content}". How can I help you with recruiting today?`,
          });
        }, 500);
      }
    } catch (error) {
      console.error('Chat error:', error);
      // Simulated response for demo
      setTimeout(() => {
        addMessage({
          role: 'assistant',
          content: `I received your message: "${content}". How can I help you with recruiting today?`,
        });
      }, 500);
    } finally {
      setIsLoading(false);
    }
  }, [addMessage, setIsLoading, loginState.cookies, currentSessionId]);

  // Export candidate
  const exportCandidate = useCallback(async (candidate: Candidate): Promise<ExportResponse> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/candidates/export`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(loginState.cookies && { 'Cookie': loginState.cookies }),
        },
        body: JSON.stringify({
          candidate,
          exportPath: settings.exportPath,
        }),
      });

      const result: ApiResponse<ExportResponse> = await response.json();

      if (result.success && result.data?.filePath) {
        addExportedFile({
          name: `${candidate.name}_resume.pdf`,
          path: result.data.filePath,
          candidateId: candidate.id,
        });
        markCandidateExported(candidate.id);
        return { success: true, filePath: result.data.filePath, message: 'Candidate exported successfully' };
      }

      return { success: false, message: result.error || 'Failed to export candidate' };
    } catch (error) {
      console.error('Export error:', error);
      // Simulate success for demo
      const mockPath = `${settings.exportPath || '/exports'}/${candidate.name.replace(/\s+/g, '_')}_resume.pdf`;
