import { useState, useRef, useEffect, KeyboardEvent } from 'react';
import { useAppStore } from '../stores/appStore';
import { useApi } from '../hooks/useApi';
import { useTheme } from './ThemeProvider';
import ReactMarkdown from 'react-markdown';
import {
  Send,
  Loader2,
  Copy,
  Check,
  RotateCcw,
  MoreVertical,
} from 'lucide-react';

export function ChatArea() {
  const { messages, isLoading, currentSessionId, addSession, deleteSession } = useAppStore();
  const { sendMessage } = useApi();
  const { theme } = useTheme();
  const [input, setInput] = useState('');
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  // Auto-scroll to bottom when messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Focus input on mount
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const message = input.trim();
    setInput('');
    await sendMessage(message);
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleCopy = (content: string, id: string) => {
    navigator.clipboard.writeText(content);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleNewChat = () => {
    addSession({ title: 'New Chat' });
    setInput('');
  };

  const handleDeleteSession = () => {
    if (currentSessionId) {
      deleteSession(currentSessionId);
    }
  };

  const bgColor = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';
  const borderColor = theme === 'dark' ? 'border-zinc-800' : 'border-zinc-200';
  const inputBgColor = theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-100';
  const userBubbleBg = theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-100';
  const assistantBubbleBg = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';
  const secondaryTextColor = theme === 'dark' ? 'text-zinc-400' : 'text-zinc-500';
  const hoverBgColor = theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-100';

  return (
    <div className={`flex flex-col h-full ${bgColor}`}>
      {/* Header */}
      <div className={`flex items-center justify-between px-6 py-4 border-b ${borderColor}`}>
        <div>
          <h1 className={`text-xl font-semibold ${textColor}`}>Boss Recruiter</h1>
          <p className={`text-sm ${secondaryTextColor}`}>
            AI-powered recruitment assistant
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={handleNewChat}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm ${hoverBgColor} ${textColor} transition-colors`}
          >
            <RotateCcw className="w-4 h-4" />
            New Chat
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto px-6 py-4">
        {messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center">
            <div className={`w-16 h-16 rounded-full ${inputBgColor} flex items-center justify-center mb-4`}>
              <span className={`text-2xl ${textColor}`}>🤖</span>
            </div>
            <h2 className={`text-xl font-semibold ${textColor} mb-2`}>
              How can I help you today?
            </h2>
            <p className={`text-sm ${secondaryTextColor} max-w-md`}>
              I can help you search for candidates, write job descriptions, or answer questions about recruitment.
            </p>
          </div>
        ) : (
          <div className="space-y-6">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] rounded-2xl px-4 py-3 ${
                    message.role === 'user'
                      ? `${userBubbleBg} ${textColor}`
                      : `${assistantBubbleBg} ${textColor} border ${borderColor}`
                  }`}
                >
                  <div className="prose prose-sm max-w-none dark:prose-invert">
                    <ReactMarkdown
                      components={{
                        code: ({ className, children, ...props }) => {
                          const match = /language-(\w+)/.exec(className || '');
                          const isInline = !match;
                          return isInline ? (
                            <code
                              className={`px-1 py-0.5 rounded ${inputBgColor} ${textColor}`}
                              {...props}
                            >
                              {children}
                            </code>
                          ) : (
                            <code className={className} {...props}>
                              {children}
                            </code>
                          );
                        },
                      }}
                    >
                      {message.content}
                    </ReactMarkdown>
                  </div>
                  <div className={`flex items-center justify-end gap-2 mt-2 ${secondaryTextColor}`}>
                    <button
                      onClick={() => handleCopy(message.content, message.id)}
                      className="p-1 rounded hover:bg-zinc-700/20 transition-colors"
                      title="Copy"
                    >
                      {copiedId === message.id ? (
                        <Check className="w-3.5 h-3.5" />
                      ) : (
                        <Copy className="w-3.5 h-3.5" />
                      )}
                    </button>
                    <span className="text-xs">
                      {new Date(message.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className={`max-w-[80%] rounded-2xl px-4 py-3 ${assistantBubbleBg} border ${borderColor}`}>
                  <div className="flex items-center gap-2">
                    <Loader2 className={`w-4 h-4 animate-spin ${secondaryTextColor}`} />
                    <span className={secondaryTextColor}>Thinking...</span>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Input */}
      <div className={`px-6 py-4 border-t ${borderColor}`}>
        <div className={`flex items-end gap-3 ${inputBgColor} rounded-xl p-2`}>
          <textarea
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type your message..."
            className={`flex-1 bg-transparent resize-none outline-none ${textColor} placeholder:${secondaryTextColor} max-h-32 min-h-[44px] py-2 px-3`}
            rows={1}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`p-2.5 rounded-lg transition-colors ${
              input.trim() && !isLoading
                ? 'bg-primary-600 text-white hover:bg-primary-700'
                : `${secondaryTextColor} cursor-not-allowed`
            }`}
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
        <p className={`text-xs ${secondaryTextColor} text-center mt-2`}>
          Press Enter to send, Shift+Enter for new line
        </p>
      </div>
    </div>
  );
}

