                    </ReactMarkdown>
                  </div>
                  <div className={`flex items-center justify-end gap-2 mt-2 ${secondaryTextColor}`}>
                    <button
                      onClick={() => handleCopy(message.content, message.id)}
                      className="p-1 rounded hover:bg-zinc-700/20 transition-colors"
                      title="Copy"
                    >
                      {copiedId === message.id ? (
                        <Check className="w-3.5 h-3.5" />
                      ) : (
                        <Copy className="w-3.5 h-3.5" />
                      )}
                    </button>
                    <span className="text-xs">
                      {new Date(message.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className={`max-w-[80%] rounded-2xl px-4 py-3 ${assistantBubbleBg} border ${borderColor}`}>
                  <div className="flex items-center gap-2">
                    <Loader2 className={`w-4 h-4 animate-spin ${secondaryTextColor}`} />
                    <span className={secondaryTextColor}>Thinking...</span>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Input */}
      <div className={`px-6 py-4 border-t ${borderColor}`}>
        <div className={`flex items-end gap-3 ${inputBgColor} rounded-xl p-2`}>
          <textarea
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type your message..."
            className={`flex-1 bg-transparent resize-none outline-none ${textColor} placeholder:${secondaryTextColor} max-h-32 min-h-[44px] py-2 px-3`}
            rows={1}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`p-2.5 rounded-lg transition-colors ${
              input.trim() && !isLoading
                ? 'bg-primary-600 text-white hover:bg-primary-700'
                : `${secondaryTextColor} cursor-not-allowed`
            }`}
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
        <p className={`text-xs ${secondaryTextColor} text-center mt-2`}>
          Press Enter to send, Shift+Enter for new line
        </p>
      </div>
    </div>
  );
}

