import { useState } from 'react';
import { useAppStore } from '../stores/appStore';
import { useApi } from '../hooks/useApi';
import { useTheme } from './ThemeProvider';
import {
  MessageCircle,
  Plus,
  Settings,
  Sun,
  Moon,
  Trash2,
  ChevronLeft,
  LogOut,
  FolderOpen,
} from 'lucide-react';

export function LeftSidebar() {
  const {
    sessions,
    currentSessionId,
    settings,
    loginState,
    leftSidebarOpen,
    toggleLeftSidebar,
    addSession,
    setCurrentSession,
    deleteSession,
    updateSettings,
    setShowLoginModal,
  } = useAppStore();
  const { logout } = useApi();
  const { theme, toggleTheme } = useTheme();
  const [showSettings, setShowSettings] = useState(false);

  const bgColor = theme === 'dark' ? 'bg-zinc-950' : 'bg-zinc-50';
  const borderColor = theme === 'dark' ? 'border-zinc-800' : 'border-zinc-200';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';
  const secondaryTextColor = theme === 'dark' ? 'text-zinc-400' : 'text-zinc-500';
  const hoverBgColor = theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-200';
  const activeBgColor = theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-200';
  const inputBgColor = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';

  const handleNewChat = () => {
    addSession({ title: 'New Chat' });
  };

  const handleSessionClick = (id: string) => {
    setCurrentSession(id);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    deleteSession(id);
  };

  const handleExportPathChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    updateSettings({ exportPath: e.target.value });
  };

  const handleLogout = async () => {
    await logout();
    setShowLoginModal(true);
  };

  if (!leftSidebarOpen) {
    return null;
  }

  return (
    <div
      className={`flex flex-col h-full ${bgColor} border-r ${borderColor} w-72 shrink-0`}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800">
        <span className={`font-semibold ${textColor}`}>Boss Recruiter</span>
        <button
          onClick={toggleLeftSidebar}
          className={`p-1.5 rounded-lg ${hoverBgColor} ${textColor} transition-colors`}
        >
          <ChevronLeft className="w-4 h-4" />
        </button>
      </div>

      {/* New Chat Button */}
      <div className="p-3">
        <button
          onClick={handleNewChat}
          className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl ${activeBgColor} ${textColor} transition-colors`}
        >
          <Plus className="w-5 h-5" />
          <span className="font-medium">New Chat</span>
        </button>
      </div>

      {/* Sessions List */}
      <div className="flex-1 overflow-y-auto px-3 py-2">
        <div className={`text-xs font-medium uppercase tracking-wider ${secondaryTextColor} px-3 mb-2`}>
          Chat History
        </div>
        {sessions.length === 0 ? (
          <div className={`text-sm ${secondaryTextColor} px-3 py-4 text-center`}>
            No conversations yet
          </div>
        ) : (
          <div className="space-y-1">
            {sessions.map((session) => (
              <div
                key={session.id}
                onClick={() => handleSessionClick(session.id)}
                className={`group flex items-center gap-3 px-3 py-2 rounded-lg cursor-pointer transition-colors ${
                  currentSessionId === session.id
                    ? activeBgColor
                    : hoverBgColor
                } ${textColor}`}
              >
                <MessageCircle className="w-4 h-4 shrink-0" />
                <span className="flex-1 truncate text-sm">{session.title || 'New Chat'}</span>
                <button
                  onClick={(e) => handleDeleteSession(e, session.id)}
                  className={`opacity-0 group-hover:opacity-100 p-1 rounded hover:bg-red-500/20 text-red-400 transition-all`}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Settings Section */}
      <div className={`border-t ${borderColor} p-3`}>
        <button
          onClick={() => setShowSettings(!showSettings)}
          className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg ${hoverBgColor} ${textColor} transition-colors`}
        >
          <Settings className="w-4 h-4" />
          <span className="flex-1 text-left text-sm">Settings</span>
        </button>

        {showSettings && (
          <div className={`mt-2 space-y-3 p-3 rounded-lg ${inputBgColor}`}>
            {/* Export Path */}
            <div>
              <label className={`text-xs ${secondaryTextColor} block mb-1.5`}>
                Export Path
              </label>
              <div className="relative">
                <FolderOpen className={`absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 ${secondaryTextColor}`} />
                <input
                  type="text"
                  value={settings.exportPath}
                  onChange={handleExportPathChange}
                  placeholder="/exports"
                  className={`w-full pl-8 pr-3 py-2 rounded-lg text-sm ${inputBgColor} border ${borderColor} ${textColor} outline-none focus:border-primary-500`}
                />
              </div>
            </div>

            {/* Theme Toggle */}
            <div>
              <label className={`text-xs ${secondaryTextColor} block mb-1.5`}>
                Theme
              </label>
              <button
                onClick={toggleTheme}
                className={`w-full flex items-center justify-between px-3 py-2 rounded-lg ${hoverBgColor} ${textColor} transition-colors`}
              >
                <span className="text-sm">{theme === 'dark' ? 'Dark Mode' : 'Light Mode'}</span>
                {theme === 'dark' ? (
                  <Moon className="w-4 h-4" />
                ) : (
                  <Sun className="w-4 h-4" />
                )}
              </button>
            </div>

            {/* Login State */}
            {loginState.isLoggedIn && (
              <button
                onClick={handleLogout}
                className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-red-500/20 text-red-400 transition-colors`}
              >
                <LogOut className="w-4 h-4" />
                <span className="text-sm">Logout</span>
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

