import { useState } from 'react';
import { useAppStore } from '../stores/appStore';
import { useTheme } from './ThemeProvider';
import {
  ChevronRight,
  FileText,
  Trash2,
  ExternalLink,
  FolderOpen,
} from 'lucide-react';

interface FilePreviewProps {
  path: string;
  onClose: () => void;
}

function FilePreview({ path, onClose }: FilePreviewProps) {
  const { theme } = useTheme();
  const bgColor = theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-100';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';
  const borderColor = theme === 'dark' ? 'border-zinc-700' : 'border-zinc-300';

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={onClose}>
      <div
        className={`max-w-lg w-full mx-4 rounded-xl ${bgColor} border ${borderColor} p-4`}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <h3 className={`font-semibold ${textColor}`}>File Preview</h3>
          <button
            onClick={onClose}
            className={`p-1 rounded-lg ${theme === 'dark' ? 'hover:bg-zinc-700' : 'hover:bg-zinc-200'} ${textColor}`}
          >
            ✕
          </button>
        </div>
        <div className={`p-3 rounded-lg ${theme === 'dark' ? 'bg-zinc-900' : 'bg-white'} border ${borderColor}`}>
          <p className={`text-sm ${textColor} break-all`}>{path}</p>
        </div>
        <div className="flex gap-2 mt-4">
          <button
            onClick={() => window.open(`file://${path}`, '_blank')}
            className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-lg bg-primary-600 text-white hover:bg-primary-700 transition-colors`}
          >
            <ExternalLink className="w-4 h-4" />
            Open
          </button>
          <button
            onClick={() => {
              navigator.clipboard.writeText(path);
              onClose();
            }}
            className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-lg ${bgColor} ${textColor} border ${borderColor} hover:bg-zinc-700 transition-colors`}
          >
            Copy Path
          </button>
        </div>
      </div>
    </div>
  );
}

export function RightSidebar() {
  const { exportedFiles, removeExportedFile, rightSidebarOpen, toggleRightSidebar } = useAppStore();
  const { theme } = useTheme();
  const [previewFile, setPreviewFile] = useState<string | null>(null);

  const bgColor = theme === 'dark' ? 'bg-zinc-950' : 'bg-zinc-50';
  const borderColor = theme === 'dark' ? 'border-zinc-800' : 'border-zinc-200';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';
  const secondaryTextColor = theme === 'dark' ? 'text-zinc-400' : 'text-zinc-500';
  const hoverBgColor = theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-200';
  const itemBgColor = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';

  const handleDeleteFile = (id: string) => {
    removeExportedFile(id);
  };

  const handlePreview = (path: string) => {
    setPreviewFile(path);
  };

  if (!rightSidebarOpen) {
    return (
      <button
        onClick={toggleRightSidebar}
        className={`fixed right-4 top-1/2 -translate-y-1/2 p-2 rounded-lg ${hoverBgColor} ${textColor} transition-colors z-10`}
      >
        <ChevronRight className="w-5 h-5" />
      </button>
    );
  }

  return (
    <>
      <div
        className={`flex flex-col h-full ${bgColor} border-l ${borderColor} w-72 shrink-0`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-zinc-800">
          <span className={`font-semibold ${textColor}`}>Exported Files</span>
          <button
            onClick={toggleRightSidebar}
            className={`p-1.5 rounded-lg ${hoverBgColor} ${textColor} transition-colors`}
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>

        {/* Files List */}
        <div className="flex-1 overflow-y-auto p-3">
          {exportedFiles.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center py-8">
              <div className={`w-12 h-12 rounded-full ${itemBgColor} flex items-center justify-center mb-3`}>
                <FolderOpen className={`w-6 h-6 ${secondaryTextColor}`} />
              </div>
              <p className={`text-sm ${secondaryTextColor}`}>
                No exported files yet
              </p>
              <p className={`text-xs ${secondaryTextColor} mt-1`}>
                Export candidates to see them here
              </p>
            </div>
          ) : (
            <div className="space-y-2">
              {exportedFiles.map((file) => (
                <div
                  key={file.id}
                  className={`group flex items-start gap-3 p-3 rounded-lg ${itemBgColor} border ${borderColor} hover:border-primary-500/50 transition-colors cursor-pointer`}
                  onClick={() => handlePreview(file.path)}
                >
                  <div className={`p-2 rounded-lg ${theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-100'}`}>
                    <FileText className={`w-4 h-4 ${secondaryTextColor}`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm font-medium truncate ${textColor}`}>
                      {file.name}
                    </p>
                    text-xs ${secondary<p className={`TextColor} truncate mt-0.5`}>
                      {file.path}
                    </p>
                    <p className={`text-xs ${secondaryTextColor} mt-1`}>
                      {new Date(file.exportedAt).toLocaleString()}
                    </p>
                  </div>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteFile(file.id);
                    }}
                    className={`opacity-0 group-hover:opacity-100 p-1.5 rounded-lg hover:bg-red-500/20 text-red-400 transition-all`}
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer Stats */}
        <div className={`border-t ${borderColor} px-4 py-3`}>
          <p className={`text-xs ${secondaryTextColor}`}>
            {exportedFiles.length} file{exportedFiles.length !== 1 ? 's' : ''} exported
          </p>
        </div>
      </div>

      {/* Preview Modal */}
      {previewFile && (
        <FilePreview path={previewFile} onClose={() => setPreviewFile(null)} />
      )}
    </>
  );
}

