import { useState, useRef, useEffect } from 'react';
import { useAppStore } from '../stores/appStore';
import { useApi } from '../hooks/useApi';
import { useTheme } from './ThemeProvider';
import {
  X,
  Phone,
  MessageSquareCode,
  Loader2,
  AlertCircle,
  CheckCircle2,
  ArrowRight,
} from 'lucide-react';

export function LoginModal() {
  const { showLoginModal, setShowLoginModal, loginState } = useAppStore();
  const { sendVerificationCode, verifyCode } = useApi();
  const { theme } = useTheme();

  const [phone, setPhone] = useState('');
  const [code, setCode] = useState('');
  const [step, setStep] = useState<'phone' | 'code'>('phone');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [countdown, setCountdown] = useState(0);

  const sliderRef = useRef<HTMLDivElement>(null);
  const [sliderPosition, setSliderPosition] = useState(0);
  const [isDragging, setIsDragging] = useState(false);

  // Reset state when modal opens
  useEffect(() => {
    if (showLoginModal) {
      setStep('phone');
      setCode('');
      setError(null);
      setSuccess(false);
      setSliderPosition(0);
    }
  }, [showLoginModal]);

  // Countdown timer
  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [countdown]);

  // Slider drag handlers
  const handleMouseDown = () => {
    setIsDragging(true);
  };

  const handleMouseUp = async () => {
    setIsDragging(false);
    if (sliderPosition > 80) {
      // Slider released past threshold - verify code
      if (step === 'code' && code.length === 6) {
        await handleVerifyCode();
      }
    }
    setSliderPosition(0);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const rect = sliderRef.current?.getBoundingClientRect();
    if (rect) {
      const x = Math.min(Math.max(e.clientX - rect.left, 0), rect.width);
      setSliderPosition((x / rect.width) * 100);
    }
  };

  const handleSendCode = async () => {
    if (!phone.match(/^1[3-9]\d{9}$/)) {
      setError('Please enter a valid phone number');
      return;
    }

    setLoading(true);
    setError(null);

    const result = await sendVerificationCode(phone);
    if (result.success) {
      setStep('code');
      setCountdown(60);
    } else {
      setError(result.message);
    }

    setLoading(false);
  };

  const handleVerifyCode = async () => {
    if (code.length !== 6) {
      setError('Please enter the 6-digit code');
      return;
    }

    setLoading(true);
    setError(null);

    const result = await verifyCode(phone, code);
    if (result.success) {
      setSuccess(true);
      setTimeout(() => {
        setShowLoginModal(false);
      }, 1500);
    } else {
      setError(result.message);
    }

    setLoading(false);
  };

  if (!showLoginModal) return null;

  const bgColor = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';
  const borderColor = theme === 'dark' ? 'border-zinc-700' : 'border-zinc-200';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';
  const secondaryTextColor = theme === 'dark' ? 'text-zinc-400' : 'text-zinc-500';
  const inputBgColor = theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-50';

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div
        className={`w-full max-w-md mx-4 rounded-2xl ${bgColor} border ${borderColor} overflow-hidden`}
      >
        {/* Header */}
        <div className={`flex items-center justify-between px-6 py-4 border-b ${borderColor}`}>
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-xl ${theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-100'}`}>
              <Phone className={`w-5 h-5 ${textColor}`} />
            </div>
            <div>
              <h2 className={`font-semibold ${textColor}`}>Login</h2>
              <p className={`text-xs ${secondaryTextColor}`}>
                {step === 'phone' ? 'Enter your phone number' : 'Enter verification code'}
              </p>
            </div>
          </div>
          <button
            onClick={() => setShowLoginModal(false)}
            className={`p-1.5 rounded-lg ${theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-100'} ${textColor}`}
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6">
          {success ? (
            <div className="flex flex-col items-center py-8">
              <div className="w-16 h-16 rounded-full bg-green-500/20 flex items-center justify-center mb-4">
                <CheckCircle2 className="w-8 h-8 text-green-500" />
              </div>
              <p className={`text-lg font-medium ${textColor}`}>Login Successful!</p>
              <p className={`text-sm ${secondaryTextColor} mt-1`}>Redirecting...</p>
            </div>
          ) : (
            <>
              {/* Phone Input */}
              {step === 'phone' && (
                <div className="space-y-4">
                  <div>
                    <label className={`text-sm ${secondaryTextColor} block mb-2`}>
                      Phone Number
                    </label>
                    <div className="relative">
                      <span className={`absolute left-3 top-1/2 -translate-y-1/2 ${secondaryTextColor}`}>
                        +86
                      </span>
                      <input
                        type="tel"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value.replace(/\D/g, ''))}
                        placeholder="Enter your phone number"
                        className={`w-full pl-12 pr-4 py-3 rounded-xl ${inputBgColor} border ${borderColor} ${textColor} outline-none focus:border-primary-500 transition-colors`}
                        maxLength={11}
                      />
                    </div>
                  </div>

                  {error && (
                    <div className="flex items-center gap-2 text-red-500 text-sm">
                      <AlertCircle className="w-4 h-4" />
                      {error}
                    </div>
                  )}

                  <button
                    onClick={handleSendCode}
                    disabled={loading || phone.length < 11}
                    className={`w-full flex items-center justify-center gap-2 px-4 py-3 rounded-xl bg-primary-600 text-white font-medium hover:bg-primary-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors`}
                  >
                    {loading ? (
                      <Loader2 className="w-5 h-5 animate-spin" />
                    ) : (
                      <>
                        Send Code
                        <ArrowRight className="w-5 h-5" />
                      </>
                    )}
                  </button>
                </div>
              )}

              {/* Code Input */}
              {step === 'code' && (
                <div className="space-y-4">
                  <div className="text-center mb-4">
                    <p className={`text-sm ${secondaryTextColor}`}>
                      Code sent to <span className={textColor}>+86 {phone}</span>
                    </p>
                    {countdown > 0 ? (
                      <p className={`text-xs ${secondaryTextColor} mt-1`}>
                        Resend in {countdown}s
                      </p>
                    ) : (
                      <button
                        onClick={handleSendCode}
                        className={`text-xs ${textColor} hover:underline mt-1`}
                      >
                        Resend code
                      </button>
                    )}
                  </div>

                  <div>
                    <label className={`text-sm ${secondaryTextColor} block mb-2`}>
                      Verification Code
                    </label>
                    <input
                      type="text"
                      value={code}
                      onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
                      placeholder="Enter 6-digit code"
                      className={`w-full px-4 py-3 rounded-xl ${inputBgColor} border ${borderColor} ${textColor} outline-none focus:border-primary-500 transition-colors text-center text-lg tracking-widest`}
                      maxLength={6}
                    />
                  </div>

                  {error && (
                    <div className="flex items-center gap-2 text-red-500 text-sm">
                      <AlertCircle className="w-4 h-4" />
                      {error}
                    </div>
                  )}

                  {/* Slider Verification */}
                  <div className="pt-2">
                    <div
                      ref={sliderRef}
                      className={`relative h-12 rounded-xl overflow-hidden ${inputBgColor} border ${borderColor}`}
                      onMouseMove={handleMouseMove}
                      onMouseUp={handleMouseUp}
                      onMouseLeave={handleMouseUp}
                    >
                      <div className="absolute inset-0 flex items-center justify-center">
                        <span className={`text-sm ${secondaryTextColor}`}>
                          Slide to verify
                        </span>
                      </div>
                      <div
                        className={`absolute top-1 bottom-1 left-1 w-10 rounded-lg bg-gradient-to-r from-primary-500 to-primary-600 flex items-center justify-center transition-all`}
                        style={{ left: `calc(${sliderPosition}% - ${sliderPosition > 0 ? sliderPosition * 0.4 : 0}px)` }}
                        onMouseDown={handleMouseDown}
                      >
                        <ArrowRight className="w-5 h-5 text-white" />
                      </div>
                    </div>
                  </div>

                  <button
                    onClick={handleVerifyCode}
                    disabled={loading || code.length !== 6}
                    className={`w-full flex items-center justify-center gap-2 px-4 py-3 rounded-xl bg-primary-600 text-white font-medium hover:bg-primary-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors`}
                  >
                    {loading ? (
                      <Loader2 className="w-5 h-5 animate-spin" />
                    ) : (
                      'Verify'
                    )}
                  </button>
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer */}
        <div className={`px-6 py-3 border-t ${borderColor}`}>
          <p className={`text-xs ${secondaryTextColor} text-center`}>
            By continuing, you agree to our Terms of Service and Privacy Policy
          </p>
        </div>
      </div>
    </div>
  );
}

