import { useEffect } from 'react';
import { useAppStore } from '../stores/appStore';
import { useApi } from '../hooks/useApi';
import { useTheme } from './ThemeProvider';
import { LeftSidebar } from './LeftSidebar';
import { RightSidebar } from './RightSidebar';
import { ChatArea } from './ChatArea';
import { CandidateCards } from './CandidateCards';
import { LoginModal } from './LoginModal';
import { Menu, Users } from 'lucide-react';

export function AppLayout() {
  const { loginState, leftSidebarOpen, toggleLeftSidebar, showCandidates, setShowLoginModal } = useAppStore();
  const { checkLoginStatus } = useApi();
  const { theme } = useTheme();

  // Check login status on mount
  useEffect(() => {
    checkLoginStatus();
  }, [checkLoginStatus]);

  // Show login modal if not logged in
  useEffect(() => {
    if (!loginState.isLoggedIn) {
      setShowLoginModal(true);
    }
  }, [loginState.isLoggedIn, setShowLoginModal]);

  const bgColor = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';
  const borderColor = theme === 'dark' ? 'border-zinc-800' : 'border-zinc-200';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';

  return (
    <div className={`h-screen flex ${bgColor}`}>
      {/* Left Sidebar */}
      <LeftSidebar />

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Mobile Header */}
        <div className={`lg:hidden flex items-center justify-between px-4 py-3 border-b ${borderColor}`}>
          {!leftSidebarOpen && (
            <button
              onClick={toggleLeftSidebar}
              className={`p-2 rounded-lg ${theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-100'} ${textColor}`}
            >
              <Menu className="w-5 h-5" />
            </button>
          )}
          <span className={`font-semibold ${textColor}`}>Boss Recruiter</span>
          <button
            onClick={() => useAppStore.getState().setShowCandidates(true)}
            className={`p-2 rounded-lg ${theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-100'} ${textColor}`}
          >
            <Users className="w-5 h-5" />
          </button>
        </div>

        {/* Chat Area */}
        <ChatArea />
      </div>

      {/* Right Sidebar */}
      <RightSidebar />

      {/* Candidate Cards Popup */}
      <CandidateCards />

      {/* Login Modal */}
      <LoginModal />
    </div>
  );
}

