  const bgColor = theme === 'dark' ? 'bg-zinc-900' : 'bg-white';
  const borderColor = theme === 'dark' ? 'border-zinc-700' : 'border-zinc-200';
  const textColor = theme === 'dark' ? 'text-zinc-100' : 'text-zinc-900';
  const secondaryTextColor = theme === 'dark' ? 'text-zinc-400' : 'text-zinc-500';
  const hoverBgColor = theme === 'dark' ? 'hover:bg-zinc-800' : 'hover:bg-zinc-50';

  // Sort candidates
  const sortedCandidates = [...candidates].sort((a, b) => {
    switch (sortBy) {
      case 'score':
        return b.matchScore - a.matchScore;
      case 'name':
        return a.name.localeCompare(b.name);
      case 'date':
        return 0;
      default:
        return 0;
    }
  });

  const handleExport = async (candidate: Candidate) => {
    if (!settings.exportPath) {
      alert('Please set an export path in settings first.');
      return;
    }

    setExportingId(candidate.id);
    try {
      const result = await exportCandidate(candidate);
      if (result.success) {
        setExportedIds((prev) => new Set(prev).add(candidate.id));
      } else {
        alert(result.message);
      }
    } finally {
      setExportingId(null);
    }
  };

  const handleClose = () => {
    setShowCandidates(false);
  };

  if (!showCandidates) return null;

  return (
    <div className="fixed inset-0 bg-black/50 flex items-end justify-center z-40">
      <div
        className={`w-full max-w-4xl h-[70vh] rounded-t-2xl ${bgColor} border-t border-x ${borderColor} flex flex-col`}
      >
        {/* Header */}
        <div className={`flex items-center justify-between px-6 py-4 border-b ${borderColor}`}>
          <div>
            <h2 className={`text-lg font-semibold ${textColor}`}>
              Candidates Found
            </h2>
            <p className={`text-sm ${secondaryTextColor}`}>
              {candidates.length} candidates match your search
            </p>
          </div>
          <div className="flex items-center gap-3">
            {/* Sort Button */}
            <div className="relative">
              <button
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg ${hoverBgColor} ${textColor} text-sm`}
              >
                <ArrowUpDown className="w-4 h-4" />
                Sort
              </button>
            </div>
            {/* View Toggle */}
            <div className={`flex rounded-lg ${theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-100'} p-0.5`}>
              <button
                onClick={() => setViewMode('cards')}
                className={`p-1.5 rounded-md transition-colors ${
                  viewMode === 'cards'
                    ? `${theme === 'dark' ? 'bg-zinc-700' : 'bg-white'} shadow`
                    : ''
                } ${textColor}`}
              >
                <LayoutGrid className="w-4 h-4" />
              </button>
              <button
                onClick={() => setViewMode('list')}
                className={`p-1.5 rounded-md transition-colors ${
                  viewMode === 'list'
                    ? `${theme === 'dark' ? 'bg-zinc-700' : 'bg-white'} shadow`
                    : ''
                } ${textColor}`}
              >
                <List className="w-4 h-4" />
              </button>
            </div>
            <button
              onClick={handleClose}
              className={`p-1.5 rounded-lg ${hoverBgColor} ${textColor}`}
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Cards/List */}
        <div className="flex-1 overflow-x-auto overflow-y-hidden p-6">
          {viewMode === 'cards' ? (
            <div className="flex gap-4 h-full pb-4">
              {sortedCandidates.map((candidate) => (
                <div
                  key={candidate.id}
                  className={`flex-shrink-0 w-64 ${theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-50'} rounded-xl border ${borderColor} p-4 flex flex-col`}
                >
                  {/* Avatar & Name */}
                  <div className="flex items-start gap-3 mb-3">
                    <div className={`w-12 h-12 rounded-full ${theme === 'dark' ? 'bg-zinc-700' : 'bg-zinc-200'} flex items-center justify-center`}>
                      <User className={`w-6 h-6 ${secondaryTextColor}`} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className={`font-semibold ${textColor} truncate`}>
                        {candidate.name}
                      </h3>
                      <p className={`text-sm ${secondaryTextColor} truncate`}>
                        {candidate.title}
                      </p>
                    </div>
                  </div>

                  {/* Company */}
                  <div className={`text-sm ${secondaryTextColor} mb-2`}>
                    {candidate.company}
                  </div>

                  {/* Match Score */}
                  <div className="flex items-center gap-2 mb-3">
                    <div className={`flex-1 h-2 rounded-full ${theme === 'dark' ? 'bg-zinc-700' : 'bg-zinc-200'}`}>
                      <div
                        className="h-full rounded-full bg-gradient-to-r from-primary-500 to-primary-600"
                        style={{ width: `${candidate.matchScore}%` }}
                      />
                    </div>
                    <span className={`text-sm font-medium ${textColor}`}>
                      {candidate.matchScore}%
                    </span>
                  </div>

                  {/* Details */}
                  <div className={`text-xs space-y-1 mb-4 ${secondaryTextColor}`}>
                    {candidate.location && (
                      <div className="flex items-center gap-1.5">
                        <MapPin className="w-3 h-3" />
                        {candidate.location}
                      </div>
                    )}
                    {candidate.experience && (
                      <div className="flex items-center gap-1.5">
                        <Briefcase className="w-3 h-3" />
                        {candidate.experience}
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="mt-auto pt-3inc-700/ border-t border-z50">
                    <button
                      onClick={() => handleExport(candidate)}
                      disabled={exportingId === candidate.id || exportedIds.has(candidate.id)}
                      className={`w-full flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                        exportedIds.has(candidate.id)
                          ? 'bg-green-600 text-white'
                          : 'bg-primary-600 text-white hover:bg-primary-700 disabled:opacity-50'
                      }`}
                    >
                      {exportingId === candidate.id ? (
                        <>
                          <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                          Exporting...
                        </>
                      ) : exportedIds.has(candidate.id) ? (
                        <>
                          <Check className="w-4 h-4" />
                          Exported
                        </>
                      ) : (
                        <>
                          <Download className="w-4 h-4" />
                          Export
                        </>
                      )}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            // List View
            <div className="space-y-2 h-full overflow-y-auto pb-4">
              {sortedCandidates.map((candidate) => (
                <div
                  key={candidate.id}
                  className={`flex items-center gap-4 p-4 rounded-xl ${theme === 'dark' ? 'bg-zinc-800' : 'bg-zinc-50'} border ${borderColor}`}
                >
                  {/* Avatar */}
                  <div className={`w-10 h-10 rounded-full ${theme === 'dark' ? 'bg-zinc-700' : 'bg-zinc-200'} flex items-center justify-center shrink-0`}>
                    <User className={`w-5 h-5 ${secondaryTextColor}`} />
                  </div>

                  {/* Info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className={`font-semibold ${textColor}`}>
                        {candidate.name}
                      </h3>
                      <span className={`px-2 py-0.5 rounded-full text-xs ${theme === 'dark' ? 'bg-zinc-700' : 'bg-zinc-200'} ${secondaryTextColor}`}>
                        {candidate.title}
                      </span>
                    </div>
                    <p className={`text-sm ${secondaryTextColor}`}>
                      {candidate.company}
                      {candidate.location && ` · ${candidate.location}`}
                    </p>
                  </div>

                  {/* Match Score */}
                  <div className="flex items-center gap-2 px-3">
                    <Star className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                    <span className={`font-medium ${textColor}`}>
                      {candidate.matchScore}%
                    </span>
                  </div>

                  {/* Actions */}
                  <button
                    onClick={() => handleExport(candidate)}
                    disabled={exportingId === candidate.id || exportedIds.has(candidate.id)}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                      exportedIds.has(candidate.id)
                        ? 'bg-green-600 text-white'
                        : 'bg-primary-600 text-white hover:bg-primary-700 disabled:opacity-50'
                    }`}
                  >
                    {exportedIds.has(candidate.id) ? (
                      <Check className="w-4 h-4" />
                    ) : (
                      <Download className="w-4 h-4" />
                    )}
                    Export
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

