    <ArrowUpDown className="w-4 h-4" />
    Sort: {sortBy === 'score' ? 'Match Score' : sortBy === 'name' ? 'Name' : 'Recent'}
  </button>
  {showSortMenu && (
    <div className={`absolute top-full left-0 mt-1 w-40 rounded-lg shadow-lg border ${borderColor} ${bgColor} z-10`}>
